const docs=$input.first().json.documents;
if(!Array.isArray(docs)||docs.length<1||docs.length>10)throw new Error('每批必须包含1至10条文档片段');
const ids=new Set();
for(const d of docs){if(!Number.isSafeInteger(d.pointId)||d.pointId<1||ids.has(d.pointId))throw new Error('pointId必须是唯一正整数');ids.add(d.pointId);if(typeof d.id!=='string'||!d.id||typeof d.title!=='string'||typeof d.text!=='string'||!d.text.trim()||d.text.length>1500)throw new Error('片段需id、title、非空text，text最多1500字符');}
return [{json:{documents:docs,input:docs.map(d=>d.title+'\n'+d.text)}}];

const docs=$('校验文档片段').first().json.documents;
const rows=$input.first().json.data;
if(!Array.isArray(rows)||rows.length!==docs.length)throw new Error('向量返回数量不匹配，未写入数据库');
const vectors=new Map(rows.map(r=>[r.index,r.embedding]));
const points=docs.map((d,i)=>{const v=vectors.get(i);if(!Array.isArray(v)||v.length!==1024||v.some(x=>!Number.isFinite(x)))throw new Error('向量格式无效，未写入数据库');return {id:d.pointId,vector:v,payload:{sourceId:d.id,title:d.title,text:d.text,embeddingModel:'text-embedding-v4',updatedAt:new Date().toISOString()}};});
return [{json:{points}}];
